/* Faint Silk 浅丝 by 落吟 | SullyOS 糯米机白框转换
   一套覆盖私聊、群聊、输入栏、双方气泡、语音和转账。
   保留原作者署名；外链图需要联网。装饰不占触控区域。 */
.sully-chat-root {
  color:#3d2c1f;
  --faint-glass:rgba(239,239,239,.18);
  --faint-edge:rgba(140,140,140,.35);
  --faint-ink:#262626;
  --faint-muted:rgba(38,38,38,.55);
}
.sully-chat-header {
  background:transparent!important;
  border:0!important;
  box-shadow:none!important;
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
  color:#3d2c1f!important;
  overflow:visible!important;
}
.sully-chat-name {
  color:#3d2c1f!important;
  font-size:18px!important;
  font-weight:600!important;
  line-height:1.25!important;
  max-width:100%;
  overflow-wrap:anywhere;
}
.sully-chat-status {color:rgba(61,44,31,.56)!important;font-size:11px!important;}
.sully-chat-token {color:#705f53!important;background:#ffffff70!important;border:1px solid #8c8c8c38!important;}
.sully-chat-avatar {
  width:50px!important;height:50px!important;
  flex-shrink:0!important;
  border-radius:50%!important;object-fit:cover!important;
  box-shadow:0 0 20px #ffffff26,0 4px 12px #0000000f!important;
}
.sully-chat-back,.sully-chat-trigger {
  width:40px!important;height:40px!important;
  min-width:40px!important;min-height:40px!important;
  flex-shrink:0!important;
  display:inline-flex!important;align-items:center!important;justify-content:center!important;
  padding:8px!important;
  color:#51443c!important;
  background:rgba(255,255,255,.2)!important;
  border:1px solid rgba(255,255,255,.3)!important;
  border-radius:50%!important;
  box-shadow:0 2px 8px #00000010!important;
  backdrop-filter:blur(10px)!important;
  -webkit-backdrop-filter:blur(10px)!important;
}
.sully-chat-buffs button {background:#ffffff7a!important;border:1px solid #8c8c8c38!important;color:#675548!important;}
/* 成对头像均由糯米机真实头像组件渲染：左侧角色，右侧当前用户。
   不再使用固定背景图；已保存的旧版 CSS 由真实顶栏的成对头像样式兼容覆盖。 */
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-header:has(.sully-chat-back.absolute) .sully-chat-name::before {
  content:"✩₊행복손에 닿을 듯 가깝다.*✩";
  display:block;margin:1px auto 2px;
  color:rgba(61,44,31,.46);
  font:italic 10px/1.15 Georgia,"Noto Serif SC",serif;
  letter-spacing:.2px;white-space:nowrap;
  pointer-events:none;
}
.sully-chat-inputbar {
  background:rgba(255,255,255,.15)!important;
  color:var(--faint-ink)!important;
  border:0!important;
  border-radius:30px 30px 0 0!important;
  box-shadow:none!important;
  backdrop-filter:blur(20px) saturate(180%)!important;
  -webkit-backdrop-filter:blur(20px) saturate(180%)!important;
}
.sully-chat-composer {min-width:0!important;gap:6px!important;align-items:center!important;}
.sully-chat-input-wrap {
  min-width:0!important;flex:1 1 0%!important;
  background:transparent!important;border:0!important;
  border-radius:24px!important;box-shadow:none!important;
  backdrop-filter:none!important;
}
.sully-chat-textarea {
  min-width:0!important;background:transparent!important;
  color:var(--faint-ink)!important;border:0!important;
  box-shadow:none!important;caret-color:#7d756f!important;
}
.sully-chat-textarea::placeholder {color:#00000059!important;}
.sully-chat-actions-button,.sully-chat-send-button {
  flex-shrink:0!important;border-radius:50%!important;
  color:#5b504a!important;
  background:#ffffff35!important;
  border:1px solid #ffffff55!important;
  box-shadow:none!important;
}
.sully-chat-emoji-suggestions,.sully-chat-panel {
  background:rgba(255,255,255,.95)!important;
  backdrop-filter:blur(20px)!important;
  -webkit-backdrop-filter:blur(20px)!important;
  border:1px solid #8c8c8c30!important;
  color:var(--faint-ink)!important;
}
/* 旧版外链贴纸图标已移除，导航和发送统一使用糯米机真实按钮图标。 */

/* 原作双方相同的半透明磨砂材质；直接写在实际气泡钩子，替换旧皮肤而非另叠一层。 */
.sully-bubble-user,.sully-bubble-ai {
  position:relative;
  min-width:0;max-width:100%;
  color:var(--faint-ink)!important;
  background:var(--faint-glass)!important;
  background-image:none!important;
  border:1px solid var(--faint-edge)!important;
  padding:7px 11px!important;
  font-size:14px!important;line-height:1.35!important;
  border-radius:16px!important;
  box-shadow:none!important;text-shadow:none!important;
  backdrop-filter:blur(16px) saturate(160%)!important;
  -webkit-backdrop-filter:blur(16px) saturate(160%)!important;
  overflow-wrap:anywhere;word-break:break-word;
}
.sully-bubble-user {border-radius:16px 16px 4px 16px!important;}
.sully-bubble-ai {border-radius:16px 16px 16px 4px!important;}
.sully-bubble-user a,.sully-bubble-ai a {color:#00376b!important;}
.sully-chat-message-content {min-width:0;overflow-wrap:anywhere;}
.sully-chat-message-sender {color:var(--faint-muted)!important;}
.sully-chat-message-avatar-img {border-radius:50%!important;}
/* 语音条沿用原有播放、暂停、字幕 DOM，仅换材质。 */
.sully-voice-bar {
  color:var(--faint-ink)!important;
  background:var(--faint-glass)!important;
  border:1px solid var(--faint-edge)!important;
  border-radius:16px!important;box-shadow:none!important;
  backdrop-filter:blur(16px) saturate(160%)!important;
}
.sully-voice-bar-button {color:#4a413a!important;background:#ffffff72!important;border-radius:50%!important;}
.sully-voice-bar-wave-segment {background:#827b75!important;}
.sully-voice-bar-toggle {color:#665d55!important;background:#ffffff49!important;}
.sully-voice-bar-transcript {color:var(--faint-ink)!important;background:#ffffff55!important;border:1px solid #8c8c8c40!important;border-radius:12px!important;}
/* 转账卡、回执、完成/退回/待收款一致；状态文字与收款/退回按钮保留。 */
.sully-chat-transfer-card,.sully-chat-transfer-receipt {
  min-width:0!important;max-width:min(100%,260px)!important;
  color:var(--faint-ink)!important;
  background:var(--faint-glass)!important;
  background-image:none!important;
  border:1px solid var(--faint-edge)!important;
  border-radius:16px!important;
  box-shadow:none!important;
  backdrop-filter:blur(16px) saturate(160%)!important;
  -webkit-backdrop-filter:blur(16px) saturate(160%)!important;
  overflow-wrap:anywhere;
}
.sully-chat-transfer-card {padding:12px 14px!important;}
.sully-chat-transfer-receipt {padding:9px 12px!important;}
.sully-chat-transfer-card[data-status],.sully-chat-transfer-receipt[data-status] {
  background:var(--faint-glass)!important;border-color:var(--faint-edge)!important;
}
.sully-chat-transfer-icon {
  color:#26262680!important;background:#ffffff55!important;
  border-radius:50%!important;
}
.sully-chat-transfer-header {border-bottom:1px solid #8c8c8c33!important;padding-bottom:7px!important;}
.sully-chat-transfer-amount {color:var(--faint-ink)!important;font-size:18px!important;font-weight:600!important;}
.sully-chat-transfer-brand,.sully-chat-transfer-note,.sully-chat-transfer-recipient,.sully-chat-transfer-status {
  color:var(--faint-muted)!important;
}
.sully-chat-transfer-status {background:#ffffff5c!important;}
.sully-chat-transfer-watermark {color:#262626!important;opacity:.14!important;}
/* 群聊红包、领取回执也归入同一份白框美化，不叠加独立浮层。 */
.sully-chat-group-root .sully-chat-group-packet,
.sully-chat-group-root .sully-chat-group-packet-receipt {
  color:var(--faint-ink)!important;
  background:var(--faint-glass)!important;
  background-image:none!important;
  border:1px solid var(--faint-edge)!important;
  border-radius:16px!important;
  box-shadow:none!important;
  backdrop-filter:blur(16px) saturate(160%)!important;
  -webkit-backdrop-filter:blur(16px) saturate(160%)!important;
}
.sully-chat-group-root .sully-chat-group-packet * {color:inherit;}
.sully-chat-system,.sully-chat-interaction {
  color:#615a55!important;background:#ffffff54!important;
  border:1px solid #8c8c8c36!important;border-radius:12px!important;
}
@media(max-width:380px) {
  .sully-chat-header .sully-chat-name {font-size:16px!important;}
  .sully-chat-back,.sully-chat-trigger {width:36px!important;height:36px!important;min-width:36px!important;min-height:36px!important;}
}
@media(prefers-reduced-motion:reduce) {
  .sully-chat-root .sully-chat-header,.sully-chat-root .sully-chat-inputbar {transition:none!important;}
}
/* Faint Silk mobile polish: native controls, lightweight cards, compact input. */

.sully-chat-root {
  --faint-ink:#393633;
  --faint-edge:rgba(104,94,91,.16);
  --faint-glass:rgba(255,255,255,.61);
  --faint-muted:rgba(70,65,61,.56);
}
.sully-chat-root .sully-chat-header {
  background:rgba(248,247,246,.76)!important;
  border:0!important;
  border-bottom:1px solid rgba(92,82,78,.09)!important;
  box-shadow:none!important;
  backdrop-filter:blur(14px)!important;
  -webkit-backdrop-filter:blur(14px)!important;
}
.sully-chat-root .sully-chat-name{font-size:17px!important;font-weight:600!important;letter-spacing:.15px!important;}
.sully-chat-root .sully-chat-status{font-size:10px!important;color:#9b948e!important;letter-spacing:.04em;}
.sully-chat-root .sully-chat-avatar{box-shadow:0 2px 10px rgba(62,55,52,.09)!important;}
/* Token/status badges move into the unobstructed upper-right corner,
   never across the paired avatars or their decorative caption. */
.sully-chat-root .sully-chat-header:has(.sully-chat-avatar-pair) .sully-chat-floating-status{
  top:2px!important;right:0!important;
  transform:none!important;
  max-width:calc(100% - 140px)!important;
  justify-content:flex-end!important;
}
.sully-chat-root .sully-chat-header:has(.sully-chat-avatar-pair) .sully-chat-token{
  border:0!important;background:rgba(255,255,255,.5)!important;
  color:#98918b!important;font-size:9px!important;
}
/* Do not paint image stickers on top of native navigation, AI or input buttons. */
.sully-chat-root .sully-chat-back,
.sully-chat-root .sully-chat-trigger,
.sully-chat-root .sully-chat-actions-button,
.sully-chat-root .sully-chat-input-wrap button[aria-label="表情面板"]{
  background-image:none!important;
  background-position:initial!important;
}
.sully-chat-root .sully-chat-back,
.sully-chat-root .sully-chat-trigger,
.sully-chat-root .sully-chat-header button[aria-label="电话"],
.sully-chat-root .sully-chat-header button[aria-label="群聊记忆规则"]{
  box-sizing:border-box!important;
  width:38px!important;height:38px!important;
  min-width:38px!important;min-height:38px!important;
  padding:8px!important;
  border-radius:50%!important;
  border:1px solid rgba(118,106,101,.13)!important;
  color:#5d5550!important;
  background:rgba(255,255,255,.52)!important;
  box-shadow:none!important;
  display:inline-flex!important;align-items:center!important;justify-content:center!important;
  backdrop-filter:none!important;-webkit-backdrop-filter:none!important;
}
.sully-chat-root .sully-chat-header button[aria-label="电话"],
.sully-chat-root .sully-chat-header button[aria-label="群聊记忆规则"]{right:46px!important;bottom:8px!important;}
.sully-chat-root .sully-chat-back > svg,
.sully-chat-root .sully-chat-trigger > svg,
.sully-chat-root .sully-chat-actions-button > svg,
.sully-chat-root .sully-chat-input-wrap button[aria-label="表情面板"] > svg{
  display:block!important;
  visibility:visible!important;opacity:1!important;
  width:20px!important;height:20px!important;
  filter:none!important;
}
.sully-chat-root .sully-chat-header button[aria-label="电话"] > svg,
.sully-chat-root .sully-chat-header button[aria-label="群聊记忆规则"] > svg{
  width:20px!important;height:20px!important;
  display:block!important;visibility:visible!important;
}
/* A single compact composer instead of four unrelated oversized icon stickers. */
.sully-chat-root .sully-chat-inputbar{
  background:rgba(248,247,246,.88)!important;
  border:0!important;border-top:1px solid rgba(92,82,78,.11)!important;
  border-radius:0!important;
  box-shadow:none!important;
  backdrop-filter:blur(16px)!important;-webkit-backdrop-filter:blur(16px)!important;
}
.sully-chat-root .sully-chat-composer{
  display:flex!important;align-items:center!important;
  gap:8px!important;
  padding:8px 10px!important;
  min-width:0!important;
}
.sully-chat-root .sully-chat-actions-button{
  box-sizing:border-box!important;
  width:40px!important;height:40px!important;min-width:40px!important;min-height:40px!important;
  padding:9px!important;
  flex-shrink:0!important;
  border:1px solid rgba(118,106,101,.18)!important;
  border-radius:50%!important;
  background:rgba(255,255,255,.62)!important;
  color:#655b54!important;
  box-shadow:none!important;
  display:flex!important;align-items:center!important;justify-content:center!important;
}
.sully-chat-root .sully-chat-input-wrap{
  box-sizing:border-box!important;min-width:0!important;flex:1 1 0%!important;
  min-height:42px!important;
  border:1px solid rgba(118,106,101,.18)!important;
  border-radius:22px!important;
  background:rgba(255,255,255,.73)!important;
  box-shadow:none!important;
  backdrop-filter:none!important;-webkit-backdrop-filter:none!important;
  padding-left:3px!important;padding-right:4px!important;
  display:flex!important;align-items:center!important;
}
.sully-chat-root .sully-chat-input-wrap:focus-within{
  border-color:rgba(118,106,101,.43)!important;
  background:rgba(255,255,255,.94)!important;
}
.sully-chat-root .sully-chat-textarea{
  min-width:0!important;
  padding:9px 8px 8px 12px!important;
  font-size:15px!important;line-height:1.45!important;
  border:0!important;background:transparent!important;
  color:#3b3530!important;
  box-shadow:none!important;
}
.sully-chat-root .sully-chat-textarea::placeholder{color:#aaa39e!important;opacity:1!important;}
.sully-chat-root .sully-chat-input-wrap button[aria-label="表情面板"],
.sully-chat-root .sully-chat-voice-trigger{
  flex-shrink:0!important;
  width:31px!important;height:35px!important;
  min-width:31px!important;
  padding:0!important;
  background:transparent!important;
  border:0!important;border-radius:50%!important;
  color:#89817a!important;box-shadow:none!important;
}
.sully-chat-root .sully-chat-input-wrap button[aria-label="表情面板"] > svg,
.sully-chat-root .sully-chat-voice-trigger > svg{width:19px!important;height:19px!important;}
.sully-chat-root .sully-chat-send-button{
  box-sizing:border-box!important;
  width:40px!important;height:40px!important;
  min-width:40px!important;min-height:40px!important;
  flex:0 0 40px!important;
  display:flex!important;align-items:center!important;justify-content:center!important;
  padding:0!important;
  border:0!important;border-radius:50%!important;
  background:#6a615c!important;color:#fff!important;
  box-shadow:0 2px 8px rgba(70,56,50,.13)!important;
  background-image:none!important;
}
.sully-chat-root .sully-chat-send-button:disabled{
  color:#aaa39e!important;background:#e7e4e1!important;
  box-shadow:none!important;
}
.sully-chat-root .sully-chat-send-button > svg{
  display:block!important;visibility:visible!important;
  width:19px!important;height:19px!important;
  opacity:1!important;
}
/* Softer strokes, a more legible message rhythm, unchanged message semantics. */
.sully-chat-root .sully-bubble-user,
.sully-chat-root .sully-bubble-ai{
  border-color:var(--faint-edge)!important;
  background:var(--faint-glass)!important;
  background-image:none!important;
  color:var(--faint-ink)!important;
  padding:8px 12px!important;
  font-size:14px!important;
  line-height:1.5!important;
  box-shadow:0 1px 2px rgba(70,60,55,.035)!important;
  text-shadow:none!important;
}
.sully-chat-root .sully-bubble-user{border-radius:16px 16px 5px 16px!important;}
.sully-chat-root .sully-bubble-ai{border-radius:16px 16px 16px 5px!important;}
.sully-chat-root .sully-voice-bar,
.sully-chat-root .sully-chat-transfer-card,
.sully-chat-root .sully-chat-transfer-receipt,
.sully-chat-group-root .sully-chat-group-packet,
.sully-chat-group-root .sully-chat-group-packet-receipt{
  background:var(--faint-glass)!important;
  border-color:var(--faint-edge)!important;
  box-shadow:0 1px 2px rgba(70,60,55,.035)!important;
}
/* 320px–380px phones: keep button tap targets and input from collapsing. */
@media(max-width:380px){
 .sully-chat-root .sully-chat-composer{gap:6px!important;padding-left:8px!important;padding-right:8px!important;}
 .sully-chat-root .sully-chat-input-wrap{padding-left:0!important;padding-right:2px!important;}
 .sully-chat-root .sully-chat-back,.sully-chat-root .sully-chat-trigger{width:36px!important;height:36px!important;min-width:36px!important;min-height:36px!important;}
 .sully-chat-root .sully-chat-header button[aria-label="电话"],
 .sully-chat-root .sully-chat-header button[aria-label="群聊记忆规则"]{right:43px!important;}
}
